  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>

    <div class="page-shell">
      <header>
        <section class="hero" aria-labelledby="page-title">
          <div class="hero-card">
            <p class="eyebrow">Cat care guide</p>
            <h1 id="page-title">FAQ about cats</h1>
            <p>
