                help cats feel safe in their territory.
              </p>
            </div>
          </aside>
        </section>
      </header>

      <main id="main-content">
        <section class="faq-panel" aria-labelledby="faq-heading">
          <div class="faq-intro">
            <div>
              <h2 id="faq-heading">Common questions</h2>
              <p>
                Select a question to reveal the answer. Every answer starts
                collapsed so you can browse at your own pace.
              </p>
            </div>
            <span class="faq-count" aria-label="6 questions">6 FAQs</span>
          </div>
          <div id="faq-root"></div>
        </section>
      </main>

      <footer>
        <p>For medical concerns, contact a licensed veterinarian.</p>
      </footer>
    </div>

    <script>
      const faqs = [
        {
          question: "How often should I feed my cat?",
          answer:
            "Most adult cats do well with two measured meals a day, though kittens and cats with medical needs may need a different schedule. Follow your veterinarian's guidance and adjust portions based on age, activity, and body condition.",
        },
        {
          question: "Why does my cat knead blankets or people?",
          answer:
            "Kneading is a normal comfort behavior that often starts in kittenhood. Cats may knead when they feel relaxed, are marking a familiar spot with scent glands in their paws, or are settling down to rest.",
        },
        {
          question: "How can I keep an indoor cat entertained?",
          answer:
            "Offer daily interactive play, window perches, scratching posts, food puzzles, climbing spaces, and rotating toys. Short play sessions that mimic hunting can help reduce boredom and support healthy exercise.",
        },
        {
          question: "What is the best way to introduce a new cat?",
          answer:
            "Use a slow introduction: start with a separate room, exchange bedding for scent familiarity, then allow brief supervised visual contact. Move at the cats' pace and separate them again if either cat becomes stressed.",
        },
        {
          question: "How many litter boxes should I have?",
          answer:
            "A helpful rule is one litter box per cat, plus one extra. Place boxes in quiet, accessible locations and scoop them daily so each cat has a clean option.",
        },
        {
          question: "When should I call a veterinarian?",
          answer:
            "Call promptly if your cat stops eating, has trouble breathing, strains in the litter box, hides unusually, vomits repeatedly, or shows sudden behavior changes. Cats often mask illness, so early advice matters.",
        },
      ];

      function Icon() {
        return `
          <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
            <path
              fill="none"
              stroke="currentColor"
              stroke-linecap="round"
              stroke-width="2.5"
              d="M12 5v14M5 12h14"
            />
          </svg>
        `;
      }

      function FAQItem({ question, answer }, index) {
        const buttonId = `faq-button-${index}`;
        const panelId = `faq-panel-${index}`;

        return `
          <div class="example">
            <h3>
              <button
                class="question-button"
                id="${buttonId}"
                type="button"
                aria-expanded="false"
                aria-controls="${panelId}"
              >
                <span>${question}</span>
                ${Icon()}
              </button>
            </h3>
            <div
              class="details"
              id="${panelId}"
              role="region"
              aria-labelledby="${buttonId}"
              hidden
            >
              <p>${answer}</p>
            </div>
          </div>
        `;
      }

      function FAQList({ items }) {
        return `
          <div class="faq-list">
            ${items.map((item, index) => FAQItem(item, index)).join("")}
          </div>
        `;
      }

      function App() {
        return FAQList({ items: faqs });
      }

      const root = document.querySelector("#faq-root");
      root.innerHTML = App();

      root.addEventListener("click", (event) => {
        const button = event.target.closest(".question-button");

        if (!button) {
          return;
        }

        const panel = document.getElementById(button.getAttribute("aria-controls"));
        const isExpanded = button.getAttribute("aria-expanded") === "true";

        button.setAttribute("aria-expanded", String(!isExpanded));
        panel.hidden = isExpanded;
      });
    </script>
